!function(){"use strict";function modeloCtrl($scope,mS,_commonSvc,modeloSvc,tS){$scope.data={},$scope.modelo={},$scope.marca={},$scope.modelos=[],$scope.marcas=[],$scope.dataSearch={pageIndex:1,pageSize:10},$scope.totalRecords=0,$scope.recordsQuantity=[5,10,25,50,100,500],$scope.getModelos=function(){try{showLoader(),$scope.modelos=[],modeloSvc.getAll($scope.dataSearch).then(response=>{$scope.modelos=response,$scope.totalRecords=$scope.modelos.length>0?$scope.modelos[0].totalRecords:0,hideLoader()}).catch(error=>{hideLoader(),console.log(error)})}catch(error){hideLoader(),console.log(error)}},$scope.getModelos(),$scope.pagechanged=function(){$scope.getModelos()},$scope.changePageSize=function(){$scope.dataSearch.pageIndex=1,$scope.getModelos()},$scope.resultModal=function(item){$scope.getModelos()},$scope.exportTableToExcel=()=>{try{showLoader();const modelos=$scope.modelos.map(item=>({codigo:item.codigo,descripcion:item.descripcion}));_commonSvc.exportTableToExcel({arr:modelos,fileName:"Modelos"})}catch(error){hideLoader(),console.log(error)}},$scope.delete=function(data){try{Swal.fire({icon:"warning",html:"<small>Esta seguro/a de eliminar este Modelo ahora?</small>",showConfirmButton:!0,confirmButtonText:"Si, eliminar",showCancelButton:!0,cancelButtonText:"No, cancelar",allowOutsideClick:!1}).then(result=>{result.isConfirmed&&(showLoader(),modeloSvc.delete(data.idModelo).then(response=>{hideLoader(),"0"==response.code&&tS.toastr("warning",response.message,response.titleSms),"1"==response.code&&(tS.toastr("success",response.message,response.titleSms),$scope.getModelos())}).catch(error=>{hideLoader(),console.log(error)}))})}catch(error){hideLoader(),console.log(error)}}}angular.module("acontPlusApp").controller("modeloCtrl",modeloCtrl),modeloCtrl.$inject=["$scope","mainService","commonService","modeloService","toastService"]}(window.angular);